func (q *Queries) UpdateCampaignStatus(ctx context.Context, arg UpdateCampaignStatusParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, updateCampaignStatus, arg.ID, arg.Status)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const updateContestantVotes = `-- name: UpdateContestantVotes :one
UPDATE contestants
SET 
    vote_count = $2,
    hv_per_transact = $3
WHERE id = $1
RETURNING id, campaign_id, user_id, display_name, photo_root, social_links, organisation_name, checkout, is_reserved_account_enabled, vote_count, hv_per_transact
`

type UpdateContestantVotesParams struct {
	ID            uuid.UUID `db:"id" json:"id"`
	VoteCount     float64   `db:"vote_count" json:"vote_count"`
	HvPerTransact float64   `db:"hv_per_transact" json:"hv_per_transact"`
}

func (q *Queries) UpdateContestantVotes(ctx context.Context, arg UpdateContestantVotesParams) (Contestant, error) {
	row := q.db.QueryRow(ctx, updateContestantVotes, arg.ID, arg.VoteCount, arg.HvPerTransact)
	var i Contestant
	err := row.Scan(
		&i.ID,
		&i.CampaignID,
		&i.UserID,
		&i.DisplayName,
		&i.PhotoRoot,
		&i.SocialLinks,
		&i.OrganisationName,
		&i.Checkout,
		&i.IsReservedAccountEnabled,
		&i.VoteCount,
		&i.HvPerTransact,
	)
	return i, err
}
